node - <<'NODE'
'use strict';
const fs=require('node:fs');
const crypto=require('node:crypto');
const path=require('node:path');
const assert=require('node:assert/strict');
const base='docs/papers211_215_sequence/scouting/finite_graph_rewiring_desk01';
const expected=['HANDOFF.md','INPUT_PINS.sha256','INTAKE.md','LOCAL_NATIVE_RECORDS.json','PRIMARY_SOURCE_RECORDS.json','PROOF_PACKAGE.md','SOURCES_AND_SUBTRACTION.md'];
assert.deepEqual(fs.readdirSync(base).sort(),expected);
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const local=JSON.parse(fs.readFileSync(path.join(base,'LOCAL_NATIVE_RECORDS.json'),'utf8'));
const source=JSON.parse(fs.readFileSync(path.join(base,'PRIMARY_SOURCE_RECORDS.json'),'utf8'));
assert.equal(local.records.length,16);
assert.deepEqual(local.scope_violation_record_indices,[4,5]);
assert.equal(source.requests.length,3);
assert.equal(source.failed_primary_access.body_read,false);
assert.equal(source.scientific_runs,0);
const pins=fs.readFileSync(path.join(base,'INPUT_PINS.sha256'),'utf8').trim().split('\n');
assert.equal(pins.length,7);
const checkedPins=pins.map(line=>{
 const m=/^([0-9a-f]{64})  (.+)$/.exec(line);
 assert(m);
 assert(!m[2].includes('finite_graph_memory_fresh_desk'));
 assert(!m[2].includes('finite_local_state_fresh_desk'));
 const b=fs.readFileSync(m[2]);
 assert.equal(sha(b),m[1]);
 return {path:m[2],sha256:m[1],bytes:b.length};
});
const exactReturnedReads=[3,6,7,10,11,12,13].map(i=>{
 const r=local.records[i];
 const m=/^sed -n '([0-9]+),([0-9]+)p' (.+)$/.exec(r.cmd);
 assert(m);
 const b=fs.readFileSync(m[3]);
 const starts=[0];
 for(let j=0;j<b.length;j++)if(b[j]===10)starts.push(j+1);
 const start=starts[Number(m[1])-1]??b.length;
 const end=starts[Number(m[2])]??b.length;
 const actual=b.subarray(start,end);
 assert(actual.equals(Buffer.from(r.output,'utf8')));
 return {record_index:i,path:m[3],bytes:actual.length,sha256:sha(actual),native_chunk_id:r.chunk_id};
});
const violationArchives=[4,5].map(i=>{
 const r=local.records[i];
 assert.equal(r.classification,'DISCLOSED_OUT_OF_SCOPE_POINTER_OVERVIEW_READ');
 assert.equal(r.exit_code,0);
 assert(r.output.length>0);
 return {record_index:i,native_chunk_id:r.chunk_id,archived_decoded_output_bytes:Buffer.byteLength(r.output),archived_decoded_output_sha256:sha(Buffer.from(r.output)),original_reopened:false};
});
const inventory=expected.map(name=>{
 const b=fs.readFileSync(path.join(base,name));
 return {name,bytes:b.length,sha256:sha(b)};
});
process.stdout.write(JSON.stringify({status:'PASS_DOCUMENTARY_ONLY',scientific_runs:0,selected_original_pins_checked:checkedPins,exact_decoded_return_to_current_original_byte_comparisons:exactReturnedReads,disclosed_scope_violation_archives:violationArchives,three_actual_browser_requests_recorded:true,first_seven_payloads:inventory,total_first_seven_payload_bytes:inventory.reduce((s,x)=>s+x.bytes,0),limitations:['Seven source pins were first measured after reads, not prelocked.','The two excluded original directories were not reopened or hashed.','Native tool records contain combined decoded output, not separately captured raw streams.','This inline command checks documents and hashes; it neither imports nor executes a scientific implementation.']},null,2)+'\n');
NODE

